 await page.route('http://127.0.0.1:4173/',(r:any)=>r.fulfill({contentType:'text/html',body:'<meta name="viewport" content="width=device-width,initial-scale=1"><div id="root"></div><script type="module" src="/tests/e2e/fixtures/back-consumers-harness.tsx"></script>'}));await page.route('**/api/**',(r:any)=>{const p=new URL(r.request().url()).pathname;let data:any={items:[],nextCursor:null};if(p==='/api/loan-records/synthetic')data={item:loan};else if(p==='/api/charge-records/synthetic')data={item:{id:'synthetic',loanId:'loan',borrowerName:loan.borrowerDisplayName,chargeDate:'2026-10-10',principalDue:'12345678',interestDue:'12345',totalPaid:'1000000',amountRemaining:'11358023',notes:loan.arrangement,repayments:[],allocations:[]}};else if(p==='/api/borrower-records/synthetic')data={item:{id:'synthetic',version:receiptVersion,name:loan.borrowerDisplayName,description:'Synthetic icon borrower',createdDate:'2026-10-10',hide:false}};else if(p==='/api/borrower-options')data={accounts:receiptClose.accounts,referrers:[]};else if(p==='/api/loan-options')data={businessDate:'2026-10-10',accounts:receiptClose.accounts};else if(p.endsWith('/close-preview'))data=receiptClose;else if(p==='/api/payment-records/synthetic')data={item:{id:'synthetic',version:receiptVersion,borrowerName:loan.borrowerDisplayName,paymentDate:'2026-10-10',amountReceived:'12345678',postedAmount:'12345678',status:'Posted',notes:loan.arrangement,receiptReference:null,agentReceiptPresent:false,allocations:[],repayments:[],cashMovements:[]}};else if(p.includes('/api/management/cash-holders/'))data={item:{id:'synthetic',version:receiptVersion,label:loan.borrowerDisplayName,name:loan.borrowerDisplayName,active:true,createdAt:'2026-10-10T00:00:00Z'}};else if(p==='/api/expense-records')data={items:[{id:'expense',paidByHolderId:'ch:tommy',expenseDate:'2026-10-10',payeeName:loan.borrowerDisplayName,amount:'12345678'}],nextCursor:null};else if(p==='/api/dashboard')data={pendingPaymentAmount:'12345678',todayProfit:'1234567',collection:{notPaid:1,partiallyPaid:2,overdue:3,fullyPaid:4},forecast:{},portfolio:{},incomeMtd:{},businessCashHeld:[]};else if(p.includes('payment-drafts'))data={ok:true,businessDate:'2026-10-10',borrower:{id:'borrower',displayName:loan.borrowerDisplayName},charges:[{id:'charge',chargeDate:'2026-10-10',loanDisplayKey:loan.borrowerDisplayName,amountRemaining:'12345678',principalRemaining:'12345678',interestRemaining:'0'}],accounts:receiptClose.accounts};return r.fulfill({json:data})});await page.goto('/');await page.evaluate(()=>(window as any).__typographyThai=true);
