async function typographyPairs(page:any){return page.locator('main dl dt').evaluateAll((labels:Element[])=>labels.map(label=>{const value=label.parentElement?.querySelector('dd');if(!value)return null;const a=getComputedStyle(label),b=getComputedStyle(value),r=value.getBoundingClientRect();return{label:label.textContent,value:value.textContent,labelSize:parseFloat(a.fontSize),valueSize:parseFloat(b.fontSize),labelWeight:Number(a.fontWeight),valueWeight:Number(b.fontWeight),right:r.right,left:r.left}}).filter(Boolean))}

test('Typography generic loan charge and close details distinguish values from Thai labels without clipping',async({page},info)=>{
 await typographyFixture(page);for(const width of [390,1440]){await page.setViewportSize({width,height:900});for(const name of ['loan-record-error','charge-record-error','loan-close-error']){await openReceiptCase(page,name);await expect(page.locator('main dl dt').first()).toBeVisible();const pairs:any[]=await typographyPairs(page);expect(pairs.length).toBeGreaterThanOrEqual(name==='loan-record-error'?15:3);for(const row of pairs){expect(row.valueSize,row.label).toBeGreaterThan(row.labelSize);expect(row.valueWeight,row.label).toBe(600);expect(row.labelWeight,row.label).toBe(400);expect(row.valueSize,row.label).toBeGreaterThanOrEqual(16);expect(row.left).toBeGreaterThanOrEqual(0);expect(row.right).toBeLessThanOrEqual(width)}expect(await page.evaluate(()=>document.documentElement.scrollWidth<=innerWidth)).toBe(true);if(name==='loan-record-error'){await page.screenshot({path:info.outputPath('typography-loan-'+width+'-th.png'),fullPage:true});await page.getByRole('button',{name:'แก้ไขสินเชื่อ',exact:true}).click();const readonly=page.locator('output.borrower-field-value');await expect(readonly).toBeVisible();expect(await readonly.evaluate((node:Element)=>Number(getComputedStyle(node).fontWeight))).toBe(600);for(const node of await page.locator('span.borrower-field-value').all())expect(await node.evaluate((value:Element)=>Number(getComputedStyle(value).fontWeight))).toBe(600);if(width===390)await page.screenshot({path:info.outputPath('typography-loan-readonly-390-th.png'),fullPage:true})}}}
});

test('Typography nested form and receiving summaries retain larger values and specialized detail scales',async({page},info)=>{
 await typographyFixture(page);for(const width of [390,1440]){await page.setViewportSize({width,height:900});await openReceiptCase(page,'loan-form');const number=page.locator('.loan-number-control input:not([type=date])').first();await expect(number).toBeEnabled();await number.fill('12345678');const formSize=await number.evaluate((input:Element)=>({value:parseFloat(getComputedStyle(input).fontSize),label:parseFloat(getComputedStyle(input.closest('label')!.querySelector('.field-title')!).fontSize),valueWeight:Number(getComputedStyle(input).fontWeight)}));expect(formSize.value).toBeGreaterThan(formSize.label);expect(formSize.value).toBeGreaterThanOrEqual(16);expect(formSize.valueWeight).toBe(400);if(width===390)await page.screenshot({path:info.outputPath('typography-loan-form-390-th.png'),fullPage:true});await openReceiptCase(page,'receiving-error');const amount=page.locator('input[inputmode=numeric]').first();await expect(amount).toBeVisible();const inputSize=await amount.evaluate((input:Element)=>({value:parseFloat(getComputedStyle(input).fontSize),label:parseFloat(getComputedStyle(input.closest('label')!.querySelector('.field-title')!).fontSize),valueWeight:Number(getComputedStyle(input).fontWeight)}));expect(inputSize.value).toBeGreaterThan(inputSize.label);const summary=await page.locator('.allocation-summary output > span').first().evaluate((node:Element)=>({label:parseFloat(getComputedStyle(node).fontSize),value:parseFloat(getComputedStyle(node.querySelector('strong')!).fontSize),valueWeight:Number(getComputedStyle(node.querySelector('strong')!).fontWeight)}));expect(summary.value).toBeGreaterThan(summary.label);expect(summary.valueWeight).toBeGreaterThanOrEqual(600);expect(inputSize.valueWeight).toBe(400);for(const[name,min]of [['payment-record-error',16.1],['typography-dashboard',20],['management-record-error',17.5]]as const){await openReceiptCase(page,name);await expect(page.locator('main dl dt').first()).toBeVisible();const pairs:any[]=await typographyPairs(page);expect(pairs.length).toBeGreaterThan(0);for(const row of pairs){expect(row.valueSize,row.label).toBeGreaterThan(row.labelSize);expect(row.valueSize,row.label).toBeGreaterThanOrEqual(min)}}await openReceiptCase(page,'typography-movement');await page.getByRole('combobox',{name:/^ประเภทรายการ/}).selectOption('Expense Reimbursement');const expense=page.locator('.management-expense-reference'),choose=expense.locator(':scope > button').first();await choose.click();const option=expense.locator('.borrower-card').first();await expect(option).toBeVisible();const referenceSizes=await option.evaluate((node:Element)=>({value:parseFloat(getComputedStyle(node).fontSize),label:parseFloat(getComputedStyle(node.closest('label')!.querySelector('.field-title')!).fontSize)}));expect(referenceSizes.value).toBeGreaterThan(referenceSizes.label);expect(referenceSizes.value).toBeGreaterThanOrEqual(16);await option.click();expect(await choose.evaluate((node:Element)=>parseFloat(getComputedStyle(node).fontSize))).toBeGreaterThanOrEqual(16);expect(await page.evaluate(()=>document.documentElement.scrollWidth<=innerWidth)).toBe(true)}
});


test('SVG record actions share edit delete semantics while distinct actions and disabled callbacks stay accessible',async({page},info)=>{
 await typographyFixture(page);await page.evaluate(()=>(window as any).__typographyThai=false);const actionPaths:Record<string,string[]>={edit:[],delete:[]};for(const[name,edit,remove]of [['borrower-record-error','Edit borrower','Delete borrower'],['loan-record-error','Edit loan','Delete loan'],['charge-record-error','Edit charge','Delete charge'],['payment-record-error','Correct payment','Delete payment']]){await openReceiptCase(page,name);for(const[key,label]of [['edit',edit],['delete',remove]]){const button=page.getByRole('button',{name:label,exact:true});await expect(button).toBeVisible();const svg=button.locator('svg.app-icon');await expect(svg).toHaveAttribute('data-icon',key);await expect(svg).toHaveAttribute('aria-hidden','true');actionPaths[key].push((await svg.locator('path').getAttribute('d'))!)}if(name==='loan-record-error'){await expect(page.getByRole('button',{name:'Close Loan',exact:true}).locator('svg')).toHaveAttribute('data-icon','loan-close');if(info.project.name.startsWith('mobile'))await page.screenshot({path:info.outputPath('svg-actions-loan-390.png'),fullPage:true})}}
 expect(new Set(actionPaths.edit).size).toBe(1);expect(new Set(actionPaths.delete).size).toBe(1);expect(actionPaths.edit[0]).not.toBe(actionPaths.delete[0]);await openReceiptCase(page,'receiving-error');const receive=page.getByRole('button',{name:'Review payment',exact:true});await expect(receive.locator('svg')).toHaveAttribute('data-icon','review');await expect(receive).toBeDisabled();await openReceiptCase(page,'icon-action-contract');const edit=page.getByRole('button',{name:'Edit record',exact:true});await expect(edit).toHaveAccessibleName('Edit record');await edit.click();expect(await page.evaluate(()=>(window as any).__iconClicks)).toBe(1);const disabled=page.getByRole('button',{name:'Delete disabled record',exact:true});await expect(disabled).toBeDisabled();await disabled.evaluate((button:HTMLButtonElement)=>button.click());expect(await page.evaluate(()=>(window as any).__iconClicks)).toBe(1);const names=await page.locator('main svg.app-icon').evaluateAll((nodes:Element[])=>nodes.map(node=>node.getAttribute('data-icon')));expect(new Set(names).size).toBe(names.length);const paths=await page.locator('main svg.app-icon path').evaluateAll((nodes:Element[])=>nodes.map(node=>node.getAttribute('d')));expect(new Set(paths).size).toBe(paths.length);await openReceiptCase(page,'icon-contact-sheet');await expect(page.locator('main svg.app-icon')).toHaveCount(60);await page.screenshot({path:info.outputPath('svg-contact-sheet.png'),fullPage:true});
});
